parameters.jsCode:
const email = String($('Restore trigger data').first()?.json?.body?.['ticket.requester.email'] ?? '').trim().toLowerCase();

const rows = $input.all();

let matched = null;
if (email) {
  for (const r of rows) {
    const row = r.json || {};
    const isActive = !(row.active === false || row.active === 0 || row.active === 'false' || row.active === '0' || row.active === 'no');
    if (!isActive) continue;
    const needle = String(row.match_value ?? '').trim().toLowerCase();
    if (!needle) continue;
    if (email.includes(needle)) { matched = row; break; }
  }
}

return [{
  json: {
    email,
    autosolve: matched !== null,
    matched_value: matched ? matched.match_value : null,
    matched_reason: (matched && matched.reason != null) ? matched.reason : null
  }
}];

const cfg = $('Get Project Config').first().json;
const trig = $('Restore trigger data').first().json;

const ticketId = trig.body['ticket.id'];
const noteBody = $('Note: Auto-solve email').first().json.note_body;

const ticket = {
  status: 'solved',
  comment: { public: false, body: noteBody }
};

// TAGS. `additional_tags` is ONLY supported on the Update Many Tickets endpoint.
// On a single-ticket PUT Zendesk silently discards it - 200 response, no tag
// event in the audit. This tag was never actually being applied. A single-ticket
// PUT only accepts `tags`, which replaces the array, so merge the existing ones.
const liveTicket = $('Get ticket status').first().json.ticket || {};
const tags = Array.isArray(liveTicket.tags) ? liveTicket.tags.slice() : [];
if (tags.indexOf('autosolve_email') === -1) {
  tags.push('autosolve_email');
}
ticket.tags = tags;

// Zendesk enforces required custom fields on the solve transition and validates
// against the INCOMING payload, not the stored ticket:
//   422 RecordInvalid - "Language: is required when solving a ticket"
// So every required field has to ride along in this one PUT.
const fields = [];

const catFieldId = Number(cfg.ticket_custom_field_category);
const catValue = cfg.category_value_duplicate_contact;
if (Number.isFinite(catFieldId) && catFieldId > 0
    && catValue !== null && catValue !== undefined && String(catValue).trim() !== '') {
  fields.push({ id: catFieldId, value: String(catValue) });
}

const langFieldId = Number(cfg.ticket_field_language_id);
const langValue = cfg.language_value_english;
if (Number.isFinite(langFieldId) && langFieldId > 0
    && langValue !== null && langValue !== undefined && String(langValue).trim() !== '') {
  fields.push({ id: langFieldId, value: String(langValue) });
}

// Rejection Complaint (record-based case 2) - required to solve on Personality.
// This path never sends a refund rejection, so it writes "no". STICKY: a ticket
// that already carries "yes" keeps it - same rule as the Zendesk ticket update
// request sub-workflow, so an earlier rejection is never erased.
let rcValue = null;
const rcFieldId = Number(cfg.ticket_field_rejection_complaint);
if (Number.isFinite(rcFieldId) && rcFieldId > 0) {
  const liveFields = Array.isArray(liveTicket.custom_fields) ? liveTicket.custom_fields : [];
  const rcCurrent = liveFields.find(f => Number(f.id) === rcFieldId);
  // Option values from cs_project_config (empty = yes / no).
  const rcYes = String(cfg.rejection_complaint_value_yes || 'yes');
  const rcNo = String(cfg.rejection_complaint_value_no || 'no');
  rcValue = (rcCurrent && rcCurrent.value === rcYes) ? rcYes : rcNo;
  fields.push({ id: rcFieldId, value: rcValue });
}

if (fields.length > 0) {
  ticket.custom_fields = fields;
}

return [{
  json: {
    ticket_id: ticketId,
    note_body: noteBody,
    fields_applied: fields.length,
    rejection_complaint: rcValue,
    tags_sent: ticket.tags,
    zendesk_body: { ticket: ticket }
  }
}];

const liveTicket = $('Get ticket status').first().json.ticket || {};
const requesterId = Number(liveTicket.requester_id);

const comments = $input.first().json.comments || [];

// Walk backwards to the newest comment written by the requester. Agent replies
// and the automation's own internal notes are skipped - matching those would
// flag our own wording back at us, and the note text itself contains the
// matched keyword.
let target = null;
for (let i = comments.length - 1; i >= 0; i--) {
  if (Number(comments[i].author_id) === requesterId) {
    target = comments[i];
    break;
  }
}

const fromRequester = target !== null;

// Fall back to the newest comment of any author rather than checking nothing at
// all. Over-matching is the preferred failure mode for a duty-of-care check.
if (!target && comments.length) {
  target = comments[comments.length - 1];
}

return [{
  json: {
    comment_id: target ? target.id : null,
    comment_text: target ? String(target.body == null ? '' : target.body) : '',
    from_requester: fromRequester,
    comment_count: comments.length
  }
}];

// === High risk keyword matching (follow-up path) ===
// Mode: "Run Once for All Items". Input = rows from Get High Risk Keywords.
//
// Matches ONLY the latest customer comment, not the ticket description. On this
// path the description is still the original first message, which the
// first-message eligibility check already evaluated.

const c = $('Extract last customer comment').first().json;

// Tier precedence. Lower rank wins. C (safety) outranks A (commercial threat),
// which outranks B (conduct). This mirrors the queue urgency: safety-review,
// then Priority, then Standard. A ticket matching several tiers is labelled with
// the highest-risk one.
const TIER_RANK = { C: 0, A: 1, B: 2 };

const TIER_TAG = {
  A: 'high-risk-legal-financial',
  B: 'high-risk-conduct',
  C: 'high-risk-safety-critical'
};

const TIER_QUEUE = {
  A: 'Priority',
  B: 'Standard',
  C: 'safety-review'
};

const TIER_LABEL = {
  A: 'Commercial threat',
  B: 'Hostility / repeat / account',
  C: 'Safety / duty of care'
};

// MATCHING RULE (October 2026). Letters are never changed, only their case.
//  - Both sides are lowercased. Accents, umlauts, Greek tonos, Vietnamese tone
//    marks and Thai vowel/tone marks are kept exactly as written: "llame" in the
//    table does not match "llamé" in a ticket and vice versa.
//  - Any run of spaces, line breaks, tabs or punctuation counts as ONE space, on
//    both sides. So "can't" matches "can’t" (iPhone apostrophe), "self harm"
//    matches "self-harm", and a phrase split by a line break or a double space
//    still matches. Only characters that are not a letter, mark or digit in any
//    alphabet are affected.
//  - The keyword must be bordered by the start/end of the text or by such a
//    space: "sue" never fires inside "issue", "sud" never inside "sudbina",
//    "24 hours" never inside "124 hours".
//  - Unicode NFC runs first. It does not change how the text looks and does not
//    remove accents. It only makes sure an accented letter is stored the same
//    way on both sides - some mail clients send "é" as "e" plus a separate
//    accent character, which would otherwise never compare equal.
//  - JavaScript lowercases the Turkish capital "İ" to "i" plus a combining dot.
//    The dot is dropped so "İADE" matches "iade".
//  - A keyword with no letters or digits at all (an emoji, "!!!") is matched
//    exactly as written instead of being skipped.
//
// Replaces the old a-z normaliser, which deleted every non-English letter and
// collapsed localized keywords into fragments such as "1", "24" or "t".
//
// Do NOT add space-insensitive fallback matching. A despaced variant of this
// caused two customers to be publicly told our product was not ours on
// 2026-09-09 (Personality tickets 685429 and 685459).
const WORD_CHAR = /[\p{L}\p{M}\p{N}]/u;

function lower(text) {
  return String(text == null ? '' : text).normalize('NFC').toLowerCase().replace(/i̇/g, 'i');
}

function prepare(text) {
  return lower(text).replace(/[^\p{L}\p{M}\p{N}]+/gu, ' ').trim();
}

// Character immediately before index i, surrogate-pair safe.
function charBefore(s, i) {
  if (i <= 0) return '';
  const c = s.charCodeAt(i - 1);
  if (c >= 0xDC00 && c <= 0xDFFF && i >= 2) return s.slice(i - 2, i);
  return s[i - 1];
}

// Character starting at index j, surrogate-pair safe.
function charAfter(s, j) {
  if (j >= s.length) return '';
  return String.fromCodePoint(s.codePointAt(j));
}

// True when needle occurs in hay with no letter or digit directly before or
// after it. Checks every occurrence, not just the first.
function containsWhole(hay, needle) {
  let from = 0;
  for (;;) {
    const i = hay.indexOf(needle, from);
    if (i === -1) return false;
    const b = charBefore(hay, i);
    const a = charAfter(hay, i + needle.length);
    if (!(b && WORD_CHAR.test(b)) && !(a && WORD_CHAR.test(a))) return true;
    from = i + 1;
  }
}

// Deliberately NOT stripping quoted history. This is a duty-of-care check and
// over-matching is the preferred failure mode.
const haystack = prepare(c.comment_text);
// Only used for keywords that contain no letters or digits at all.
const haystackRaw = lower(c.comment_text);

const rows = $input.all();

// One entry per distinct keyword. The localized lists repeat many terms across
// languages (chargeback, gdpr, trustpilot ...), so a keyword is listed once in
// the note, with every language it came from, and keeps its highest-risk tier.
const byNeedle = new Map();

for (const r of rows) {
  const row = r.json || {};

  // Fail-open on active: only an explicit negative disables a row, so a null
  // (never set) counts as active.
  const isActive = !(row.active === false || row.active === 0
    || row.active === 'false' || row.active === '0' || row.active === 'no');
  if (!isActive) continue;

  let needle = prepare(row.keyword);
  let hay = haystack;
  if (!needle) {
    needle = lower(row.keyword).trim();
    hay = haystackRaw;
  }
  if (!needle) continue;

  const tier = String(row.tier == null ? '' : row.tier).trim().toUpperCase();
  if (!(tier in TIER_RANK)) continue;

  if (!containsWhole(hay, needle)) continue;

  const lang = String(row.language == null ? '' : row.language).trim().toLowerCase();
  const category = String(row.category == null ? '' : row.category);
  const prev = byNeedle.get(needle);

  if (!prev) {
    byNeedle.set(needle, {
      keyword: String(row.keyword).trim(),
      needle: needle,
      tier: tier,
      category: category,
      languages: lang ? [lang] : []
    });
  } else {
    if (lang && prev.languages.indexOf(lang) === -1) prev.languages.push(lang);
    if (TIER_RANK[tier] < TIER_RANK[prev.tier]) {
      prev.tier = tier;
      prev.category = category;
    }
  }
}

const matches = Array.from(byNeedle.values());

// Highest-risk tier first, then longest (most specific) phrase within that tier.
matches.sort((a, b) => {
  const r = TIER_RANK[a.tier] - TIER_RANK[b.tier];
  if (r !== 0) return r;
  return b.needle.length - a.needle.length;
});

// Language suffix for the note. Omitted for English-only keywords so existing
// notes read exactly as before.
function langSuffix(m) {
  const l = m.languages;
  if (!l.length || (l.length === 1 && l[0] === 'en')) return '';
  const shown = l.length > 5 ? l.slice(0, 5).join(', ') + ' +' + (l.length - 5) : l.join(', ');
  return ' [' + shown + ']';
}

const winner = matches.length ? matches[0] : null;

return [{
  json: {
    high_risk_matched: matches.length > 0,
    match_count: matches.length,
    tier: winner ? winner.tier : null,
    tier_label: winner ? TIER_LABEL[winner.tier] : null,
    category: winner ? winner.category : null,
    queue: winner ? TIER_QUEUE[winner.tier] : null,
    tag: winner ? TIER_TAG[winner.tier] : null,
    primary_match: winner ? winner.keyword : null,
    matched_keywords: matches.map(m => m.keyword),
    matched_detail: matches.map(m => m.tier + '/' + m.category + ': ' + m.keyword + langSuffix(m)),
    tiers_matched: matches.map(m => m.tier).filter((t, i, a) => a.indexOf(t) === i),
    languages_matched: matches.reduce((acc, m) => acc.concat(m.languages), []).filter((l, i, a) => a.indexOf(l) === i),
    rows_checked: rows.length,
    matched_comment_id: c.comment_id,
    comment_from_requester: c.from_requester,
    haystack_chars: haystack.length
  }
}];

const cfg = $('Get Project Config').first().json;
const trig = $('Restore trigger data').first().json;
const m = $('Match High Risk Keywords').first().json;

const ticketId = trig.body['ticket.id'];

// cs_project_config.high_risk_enforce
//   OFF (default) = monitoring. Tag + internal note only, automation continues.
//   ON            = tag + note + status open + allow_automation _no_, automation stops.
const flag = cfg.high_risk_enforce;
const enforce = (flag === true || flag === 1 || flag === 'true' || flag === '1' || flag === 'yes');

const lines = [
  'Note: This follow-up message matched the high-risk keyword list.',
  '',
  'Tier: ' + m.tier + ' - ' + m.tier_label,
  'Category: ' + m.category,
  'Queue: ' + m.queue,
  'Tag applied: ' + m.tag,
  'Matched phrase: "' + m.primary_match + '"'
];

if (m.match_count > 1) {
  lines.push('');
  lines.push('All ' + m.match_count + ' matches:');
  for (const d of m.matched_detail) {
    lines.push('  - ' + d);
  }
}

lines.push('');

if (enforce) {
  lines.push('Automation has been stopped and no reply was sent to the customer.');
  lines.push('Please pick this ticket up from the ' + m.queue + ' queue and handle it manually.');
} else {
  lines.push('MONITORING MODE: the ticket was tagged and this note added, but automation was NOT stopped.');
  lines.push('The bot may still reply to this customer. No agent action is required unless the reply is wrong.');
}

const noteBody = lines.join('\n');

const ticket = {
  comment: { public: false, body: noteBody }
};

// TAGS. `additional_tags` is ONLY supported on the Update Many Tickets endpoint.
// On a single-ticket PUT Zendesk silently discards it - 200 response, no tag
// event in the audit (Personality ticket 687990). A single-ticket PUT only
// accepts `tags`, which REPLACES the array, so the existing tags are merged in
// from the live Get ticket status read.
const liveTicket = $('Get ticket status').first().json.ticket || {};
const existingTags = Array.isArray(liveTicket.tags) ? liveTicket.tags.slice() : [];

if (m.tag && existingTags.indexOf(m.tag) === -1) {
  existingTags.push(m.tag);
}
ticket.tags = existingTags;

if (enforce) {
  // Setting to open is not a solve transition, so Zendesk does not enforce
  // required custom fields here and the category does not need to ride along.
  const openStatusId = Number(cfg.ticket_custom_status_open_id);
  if (Number.isFinite(openStatusId) && openStatusId > 0) {
    ticket.custom_status_id = openStatusId;
  }

  // Stop automation re-engaging on any further replies.
  const allowFieldId = Number(cfg.ticket_field_allow_automation);
  if (Number.isFinite(allowFieldId) && allowFieldId > 0) {
    ticket.custom_fields = [{ id: allowFieldId, value: '_no_' }];
  }
}

return [{
  json: {
    ticket_id: ticketId,
    enforce: enforce,
    tier: m.tier,
    queue: m.queue,
    tag: m.tag,
    tags_sent: ticket.tags,
    primary_match: m.primary_match,
    match_count: m.match_count,
    matched_comment_id: m.matched_comment_id,
    note_body: noteBody,
    zendesk_body: { ticket: ticket }
  }
}];

// === Case 7b: customer repeatedly refuses the automated resolution ===
//
// Signal is Zendesk's own `reopens` counter: the number of solved -> open
// transitions on this ticket. Verified on Personality 2026-09: every reopen
// examined was caused by the requester replying. The automation never reopens a
// ticket it has solved.
//
// WHY REOPENS AND NOT "COUNT THE CUSTOMER'S REPLIES":
// the automation also sends NON-resolution public replies - the
// password_account_info macros ask the customer for their account email and
// leave the ticket PENDING. A customer answering that is cooperating, not
// refusing. Pending is not a solve, so it produces no reopen, and those
// customers are excluded for free. Counting replies would have flagged the most
// cooperative customers we have.
//
// KNOWN LIMITATION: a thank-you reply also reopens a solved ticket. At a
// threshold of 2 this mostly washes out, because gratitude is terminal - people
// do not thank you twice - whereas refusal repeats. Sampled ticket 688115
// (1 reopen, a thank-you) correctly does not fire; 688143 (3 reopens, two
// genuine pushbacks plus a closing thank-you) correctly does.
//
// A customer who pushes back once, hard, and then gives up registers a single
// reopen and will NOT flag. Under-flagging is the intended failure direction.

const cfg = $('Get Project Config').first().json || {};
const resp = $('Get ticket status').first().json || {};
const ticket = resp.ticket || {};

// The sideload arrives either inline on the ticket or as a sibling array,
// depending on endpoint. Accept both.
let metricSet = null;
if (ticket.metric_set) {
  metricSet = ticket.metric_set;
} else if (Array.isArray(resp.metric_sets) && resp.metric_sets.length) {
  metricSet = resp.metric_sets[0];
}

const available = !!metricSet;
const reopens = available ? Number(metricSet.reopens || 0) : null;
const replies = available ? Number(metricSet.replies || 0) : null;

const rawThreshold = Number(cfg.record_repeat_refusal_threshold);
const threshold = (Number.isFinite(rawThreshold) && rawThreshold > 0) ? rawThreshold : 2;

const matched = available && reopens >= threshold;

return [{
  json: {
    rr_metrics_available: available,
    rr_reopens: reopens,
    rr_replies: replies,
    rr_threshold: threshold,
    rr_matched: matched,
    rr_ticket_id: $('Restore trigger data').first().json.body['ticket.id']
  }
}];

const cfg = $('Get Project Config').first().json;
const trig = $('Restore trigger data').first().json;
const r = $('RR: Evaluate reopens').first().json;

const ticketId = trig.body['ticket.id'];

// cs_project_config.record_checks_enforce
//   OFF (default) = monitoring. Tag + internal note only, automation continues.
//   ON            = tag + note + status open + allow_automation _no_, automation stops.
const flag = cfg.record_checks_enforce;
const enforce = (flag === true || flag === 1 || flag === 'true' || flag === '1' || flag === 'yes');

const lines = [
  'Note: This ticket matched record-based case 7b - the customer repeatedly refuses the automated resolution.',
  '',
  'Times the customer reopened this ticket after it was solved: ' + r.rr_reopens,
  'Threshold: ' + r.rr_threshold,
  '',
  'Reopens count only replies that arrived AFTER the ticket was solved, so replies to a pending information request are not included.'
];

lines.push('');

if (enforce) {
  lines.push('Automation has been stopped and no reply was sent to the customer.');
  lines.push('Please review the conversation and handle this ticket manually.');
} else {
  lines.push('MONITORING MODE: the ticket was tagged and this note added, but automation was NOT stopped.');
  lines.push('The bot may still reply to this customer. No agent action is required unless the reply is wrong.');
}

const noteBody = lines.join('\n');

const ticket = {
  comment: { public: false, body: noteBody }
};

// TAGS. `additional_tags` is ONLY supported on the Update Many Tickets endpoint.
// On a single-ticket PUT Zendesk silently discards it - 200 response, no tag
// event in the audit. A single-ticket PUT only accepts `tags`, which REPLACES
// the array, so the existing tags are merged in from the live Get ticket status
// read.
const liveTicket = $('Get ticket status').first().json.ticket || {};
const existingTags = Array.isArray(liveTicket.tags) ? liveTicket.tags.slice() : [];

const TAG = 'record_case_7b';
if (existingTags.indexOf(TAG) === -1) {
  existingTags.push(TAG);
}
ticket.tags = existingTags;

if (enforce) {
  // Setting to open is not a solve transition, so Zendesk does not enforce
  // required custom fields here and the category does not need to ride along.
  const openStatusId = Number(cfg.ticket_custom_status_open_id);
  if (Number.isFinite(openStatusId) && openStatusId > 0) {
    ticket.custom_status_id = openStatusId;
  }

  // Stop automation re-engaging on any further replies.
  const allowFieldId = Number(cfg.ticket_field_allow_automation);
  if (Number.isFinite(allowFieldId) && allowFieldId > 0) {
    ticket.custom_fields = [{ id: allowFieldId, value: '_no_' }];
  }
}

return [{
  json: {
    ticket_id: ticketId,
    enforce: enforce,
    reopens: r.rr_reopens,
    threshold: r.rr_threshold,
    tag: TAG,
    tags_sent: ticket.tags,
    note_body: noteBody,
    zendesk_body: { ticket: ticket }
  }
}];

// Re-emit the original passthrough payload from the execute-workflow trigger.
// Get Project Config replaces the incoming item with the config row, so we
// restore the ticket data here for every downstream check to reference via
// $('Restore trigger data').
return $('When Executed by Another Workflow').all();

// === Email blocklist filter ===
// Mode: "Run Once for All Items".
// Input to this node = rows from the "Get Email Blocklist" Data Table node.

// 1) Requester email, from the restored trigger payload.
const email = String(
  $('Restore trigger data').first()?.json?.body?.['ticket.requester.email'] ?? ''
).trim().toLowerCase();

// 2) Blocklist rows (each input item = one row from the data table).
const rows = $input.all();

// 3) First active rule whose match_value is contained in the email wins.
let matched = null;
if (email) {
  for (const r of rows) {
    const row = r.json || {};
    const isActive = !(row.active === false || row.active === 0
      || row.active === 'false' || row.active === '0' || row.active === 'no');
    if (!isActive) continue;
    const needle = String(row.match_value ?? '').trim().toLowerCase();
    if (!needle) continue;
    if (email.includes(needle)) { matched = row; break; }
  }
}

// 4) One decision item out.
return [{
  json: {
    email,
    blocked: matched !== null,
    matched_value: matched ? matched.match_value : null,
    matched_reason: (matched && matched.reason != null) ? matched.reason : null,
  },
}];

const currentTicketId = $('Restore trigger data').first().json.body['ticket.id'];
const tickets = $input.first().json.tickets || [];

// Any OTHER ticket for this requester, regardless of status.
const otherTickets = tickets.filter(t => String(t.id) !== String(currentTicketId));

const proceed = otherTickets.length === 0;

return [{
  json: {
    proceed,
    unhandled_ticket_count: otherTickets.length,        // key kept so the note node still works
    other_unhandled_ticket_ids: otherTickets.map(t => t.id)
  }
}];

parameters.value:
=User eligibility failed:
Fail reason: {{ $json.fail_reason }}
Note: {{ $json.note_body }}

Please handle this request manually.
